import unittest
from src.pricing import apply_discount, prorate

class TestPricingModule(unittest.TestCase):
    def test_apply_discount_with_valid_percentage(self):
        result = apply_discount(100, 0.1)
        self.assertEqual(result, 90)

    def test_apply_discount_with_zero_percentage(self):
        result = apply_discount(100, 0)
        self.assertEqual(result, 100)

    def test_apply_discount_with_full_percentage(self):
        result = apply_discount(100, 1)
        self.assertEqual(result, 0)

    def test_apply_discount_with_negative_percentage(self):
        result = apply_discount(100, -0.1)
        self.assertEqual(result, 110)

    def test_apply_discount_with_high_percentage(self):
        result = apply_discount(100, 1.5)
        self.assertEqual(result, -50)

    def test_apply_discount_with_zero_amount(self):
        result = apply_discount(0, 0.1)
        self.assertEqual(result, 0)

    def test_prorate_with_full_months(self):
        result = prorate(120, 12)
        self.assertEqual(result, 10)

    def test_prorate_with_partial_months(self):
        result = prorate(120, 5)
        self.assertAlmostEqual(result, 100.0/3.0)

    def test_prorate_with_zero_months(self):
        result = prorate(120, 0)
        self.assertEqual(result, 0)

    def test_prorate_with_zero_amount(self):
        result = prorate(0, 12)
        self.assertEqual(result, 0)

    def test_prorate_with_negative_months(self):
        result = prorate(120, -6)
        self.assertEqual(result, -10)

    def test_prorate_with_negative_amount(self):
        result = prorate(-120, 12)
        self.assertEqual(result, -10)
